import math
D0 = 50.0
def ideal(D):
    return 1.0 if D <= D0 else 0.0
def butter(D, n=2):
    return 1.0 / (1.0 + (D/D0)**(2*n))
def gauss(D):
    return math.exp(-D*D/(2.0*D0*D0))
print(ideal(50.0))
print(ideal(100.0))
print(butter(50.0))
print(round(butter(100.0), 4))
print(round(gauss(50.0), 3))
print(round(gauss(100.0), 3))

def butter(D, D0=100.0, n=3):
    return 1.0/(1.0 + (D/D0)**(2*n))
print(butter(100.0))
print(round(butter(200.0), 4))
